 24→  @IsNotEmpty()
 25→  @Matches(/^[0-9a-fA-F]+$/, {
 26→    message: 'encryptedRootFolderKey must be hex-encoded',
 27→  })
 28→  encryptedRootFolderKey!: string;
 29→
